+#[derive(Debug)]
+pub(crate) struct WindowLease(EntropyBudget);
+impl Drop for WindowLease {
+    fn drop(&mut self) { self.0.0.live.fetch_sub(4 * 1024 * 1024, Ordering::Relaxed); }
+}
